import { Avatar, AvatarImage, AvatarFallback } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";

export default function DoctorCard({ doctor, onAction, actionLabel = "View Profile" }) {
  return (
    <div className="bg-white rounded-xl shadow-md p-4 flex flex-col items-center gap-3 border hover:shadow-lg transition">
      <Avatar className="w-16 h-16">
  <AvatarImage
    src={
      doctor?.avatarUrl
        ? `http://localhost:5000${doctor.avatarUrl}`
        : "/default-avatar.png"
    }
    alt={doctor?.fullName || "Doctor Avatar"}
    onError={(e) => {
      e.currentTarget.src = "/default-avatar.png";
    }}
  />
  <AvatarFallback>
    {doctor?.fullName?.[0] || "U"}
  </AvatarFallback>
</Avatar>

      <div className="text-lg font-semibold text-gray-800 text-center">{doctor.fullName}</div>
      <div className="text-blue-600 text-sm font-medium">{doctor.specialization}</div>
      <div className="text-gray-500 text-xs mb-2">{doctor.experience} yrs experience</div>
      <Button size="sm" className="w-full" onClick={() => onAction?.(doctor)}>{actionLabel}</Button>
    </div>
  );
} 